export const ALL_RAW_MOCK_500: CompactMockItem[] = [
  ...RAW_MOCK_500,
  ...RAW_MOCK_500_PART2,
];

function mapCategory(cat: CompactMockItem['cat']): QuestionCategory {
  if (cat === 'Math') return 'Mathematics';
  if (cat === 'Eng') return 'English';
  if (cat === 'Mains') return 'Descriptive & Translation';
  return 'General Knowledge';
}

function mapAutoType(cat: CompactMockItem['cat']): AutoQuestionType {
  if (cat === 'Math') return 'math-step-by-step';
  if (cat === 'Mains') return 'descriptive-model-guide';
  return 'objective-concise';
}

export function convertCompactMockToQuestionItem(item: CompactMockItem): QuestionItem {
  const testIndex = Math.floor((item.qNum - 1) / 100) + 1;
  const questionNumberInTest = ((item.qNum - 1) % 100) + 1;
  const paperId = `cbt-mock-test-${testIndex}`;
  const paperShortTitle = `Mock Test ${testIndex}`;
  const category = mapCategory(item.cat);
  const autoType = mapAutoType(item.cat);

  if (item.cat === 'Mains') {
    const formatType = item.mainsType || 'Précis / Summary Writing';
    return {
      id: `MOCK-Q${item.qNum}`,
      paperId,
      paperShortTitle,
      autoType: 'descriptive-model-guide',
      seriesNumbers: {
        A: questionNumberInTest,
        B: questionNumberInTest,
        C: questionNumberInTest,
        D: questionNumberInTest,
      },
      pdfPages: { A: 1, B: 1, C: 1, D: 1 },
      category: 'Descriptive & Translation',
      subTopic: item.topic,
      questionEn: item.q,
      directAnswerSummary: item.exp,
      keyFormulaOrConcept: `WBPSC Clerkship Part-II (Mains) — ${formatType}`,
      steps: [
        {
          title: 'Step 1 — Understand the Official WBPSC Mains Requirement',
          explanation: `Carefully read the prompt under ${item.topic}. Maintain clarity, grammatical accuracy, and formal tone expected in WBPSC Clerkship Part-II.`,
        },
        {
          title: 'Step 2 — Complete Solved Model Answer',
          explanation: item.exp,
        },
      ],
      descriptiveGuide: {
        formatType,
        marks: 20,
        wordLimitOrTarget:
          formatType === 'Précis / Summary Writing'
            ? 'One-third of original passage (~45–50 words) + Suitable Title'
            : 'Idiomatic & Accurate Sentence-by-Sentence Translation',
        outlineStructure: [
          'Read the source passage carefully to identify the core theme and tone.',
          formatType === 'Précis / Summary Writing'
            ? 'Draft a concise, impactful title and summarize key points in your own words without examples or repetition.'
            : 'Translate each sentence preserving tense, administrative vocabulary, and natural syntax.',
          'Review spelling, punctuation, and coherence before final submission.',
        ],
        keyThemesAndArguments: [
          item.topic,
          item.mainsTitle || 'WBPSC Clerkship Part-II Model Solution',
        ],
        sampleAnswerTitle: item.mainsTitle || item.topic,
        sampleAnswerBody: item.exp,
      },
    };
  }

  const opts = item.opts || ['Option A', 'Option B', 'Option C', 'Option D'];
  const ans: OptionKey = item.ans || 'B';
  const correctIdx = ans === 'A' ? 0 : ans === 'B' ? 1 : ans === 'C' ? 2 : 3;
  const correctText = opts[correctIdx];

  return {
    id: `MOCK-Q${item.qNum}`,
    paperId,
    paperShortTitle,
    autoType,
    seriesNumbers: {
      A: questionNumberInTest,
      B: questionNumberInTest,
      C: questionNumberInTest,
      D: questionNumberInTest,
    },
    pdfPages: { A: 1, B: 1, C: 1, D: 1 },
    category,
    subTopic: item.topic,
    questionEn: item.q,
    options: {
      A: { en: opts[0] },
      B: { en: opts[1] },
      C: { en: opts[2] },
      D: { en: opts[3] },
    },
    correctOption: ans,
    directAnswerSummary: `Option (${ans}) — ${correctText}`,
    keyFormulaOrConcept: item.latex
      ? `Key Formula: ${item.latex}`
      : `${category} • ${item.topic}`,
    steps: [
      {
        title:
          item.cat === 'Math'
            ? 'Step 1 — Mathematical Formula & Setup'
            : 'Step 1 — Core Concept & Rule',
        explanation: item.exp,
        formulaLatex: item.latex,
      },
      {
        title: 'Step 2 — Verified Correct Option',
        explanation: `Therefore, the correct answer is Option (${ans}): ${correctText}.`,
      },
    ],
  };
}

export const INITIAL_MOCK_QUESTIONS: QuestionItem[] = ALL_RAW_MOCK_500.map(
  convertCompactMockToQuestionItem
);

