/**
 * Dynamically groups the Mock Question Bank sequentially into 100-question Mock Tests.
 * Uses Math.ceil(mockQuestions.length / 100) so uploading a new 500-question PDF
 * automatically creates Mock Test 6 through Mock Test 10.
 */
export function buildMockTestsFromPool(
  mockQuestions: QuestionItem[]
): MockTestDefinition[] {
  const totalTests = Math.ceil(mockQuestions.length / 100);
  const tests: MockTestDefinition[] = [];

  for (let i = 0; i < totalTests; i++) {
    const testNumber = i + 1;
    const startIdx = i * 100;
    const slice = mockQuestions.slice(startIdx, startIdx + 100).map((q, idx) => {
      const qNo = idx + 1;
      return {
        ...q,
        paperId: `cbt-mock-test-${testNumber}`,
        paperShortTitle: `Mock Test ${testNumber}`,
        seriesNumbers: { A: qNo, B: qNo, C: qNo, D: qNo },
      };
    });

    const mcqCount = slice.filter((q) => Boolean(q.options && q.correctOption)).length;
    const mainsCount = slice.length - mcqCount;

    tests.push({
      testNumber,
      testId: `cbt-mock-test-${testNumber}`,
      title: `Mock Test ${testNumber}`,
      subtitle: `${slice.length} Questions (Q1 to Q${slice.length})`,
      questionRangeLabel: `Q1 to Q${slice.length}`,
      questions: slice,
      mcqCount,
      mainsCount,
      durationMinutes: 90,
      totalMarks: slice.length,
    });
  }

  return tests;
}
